# API-Football's league ids of our six competitions.
LEAGUE_IDS = {"PL": 39, "PD": 140, "SA": 135, "BL1": 78, "FL1": 61, "CL": 2}


def set_league_ids(apps, schema_editor):
    Competition = apps.get_model("sports", "Competition")
    for code, league_id in LEAGUE_IDS.items():
        Competition.objects.filter(code=code, api_football_id__isnull=True).update(api_football_id=league_id)


def open_live_item(apps, schema_editor):
    # The live page is built: the sidebar stops showing it as "soon".
    apps.get_model("header", "SidebarItem").objects.filter(url="/live").update(is_soon=False)


